"""Author domain-specific screen contracts; retain the first-pass implementation aliases."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
rows=json.loads((root/'docs/module-00/screen-register.json').read_text())
screens={r['id']:{'id':r['id'],'name':r['name'],'family':r['role'],'kind':'','summary':'','fields':[],'columns':[],'rows':[],'links':[],'sections':[]} for r in rows}
def configure(sid,kind,summary,fields='',columns='',records=None,links='',sections=None):
 s=screens[sid];s.update(kind=kind,summary=summary,fields=[],columns=columns.split('|') if columns else [],rows=records or [],links=links.split('|') if links else [],sections=sections or [])
 for part in fields.split('|') if fields else []:
  bits=part.split(':');label=bits[0];typ=bits[1] if len(bits)>1 else 'text'
  s['fields'].append({'key':label.lower().replace(' ','-'),'label':label,'type':typ,'required':not label.endswith('(optional)'),'options':bits[2].split(',') if len(bits)>2 else []})
 return s
def batch(ids,kind,summary,fields='',columns='',records=None,links=''):
 for sid in ids.split():configure(sid,kind,summary,fields,columns,records,links)
